package com.aidevos.orchestrator.controller;
import java.util.List; import com.aidevos.orchestrator.qualitygate.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class QualityGateController { private final QualityGateService service; public QualityGateController(QualityGateService s){service=s;} @PostMapping("/validations/{runId}/quality-gate") public QualityGateResult evaluate(@PathVariable String runId){return service.evaluate(runId);} @GetMapping("/validations/{runId}/quality-gates") public List<QualityGateResult> byValidation(@PathVariable String runId){return service.byValidation(runId);} @GetMapping("/quality-gates/{id}") public QualityGateResult get(@PathVariable String id){return service.get(id);} @PostMapping("/quality-gates/{id}/approve") public QualityGateResult approve(@PathVariable String id,@RequestBody(required=false) Review body){return service.approve(id,body==null?"SYSTEM":body.reviewer(),body==null?null:body.comment());} @PostMapping("/quality-gates/{id}/reject") public QualityGateResult reject(@PathVariable String id,@RequestBody(required=false) Review body){return service.reject(id,body==null?"SYSTEM":body.reviewer(),body==null?null:body.comment());} public record Review(String reviewer,String comment){} }
